'use client';

import { useId } from 'react';
import type { ReactNode } from 'react';
import './feature-bento.css';

export interface FeatureBentoItem {
  id: string;
  title: string;
  description: string;
  /** Decorative artwork only; keep meaningful information in the title and description. */
  media?: ReactNode;
  eyebrow?: string;
  span?: 'default' | 'wide' | 'tall';
  href?: string;
  linkLabel?: string;
}

export interface FeatureBentoProps {
  items: FeatureBentoItem[];
  title?: string;
  className?: string;
}

/** A responsive product-benefits grid, with optional links and decorative previews. */
export function FeatureBento({ items, title = 'Small details. A better day.', className = '' }: FeatureBentoProps) {
  const headingId = useId();
  if (!items.length) return null;

  return (
    <section className={`ac-feature-bento ${className}`.trim()} aria-labelledby={headingId}>
      <header className="ac-feature-bento-header">
        <span>MADE FOR YOUR EVERYDAY</span>
        <h2 id={headingId}>{title}</h2>
      </header>
      <div className="ac-feature-bento-grid">
        {items.map(item => (
          <article className={`ac-feature-bento-card ac-feature-bento-${item.span ?? 'default'}`} key={item.id}>
            {item.media && <div className="ac-feature-bento-media" aria-hidden="true" ref={node => { if (node) node.setAttribute('inert', ''); }}>{item.media}</div>}
            <div className="ac-feature-bento-copy">
              {item.eyebrow && <span className="ac-feature-bento-eyebrow">{item.eyebrow}</span>}
              <h3>{item.title}</h3>
              <p>{item.description}</p>
              {item.href && <a href={item.href} className="ac-feature-bento-link">{item.linkLabel ?? `Explore ${item.title}`}<span aria-hidden="true">↗</span></a>}
            </div>
          </article>
        ))}
      </div>
    </section>
  );
}

.ac-feature-bento {
  --ac-bento-surface: #f0eee8;
  --ac-bento-card: #faf9f3;
  --ac-bento-media: #e3e4da;
  --ac-bento-ink: #2c3429;
  --ac-bento-muted: #65705d;
  --ac-bento-accent: #405c35;
  --ac-bento-line: #2c34291f;
  --ac-bento-font: inherit;
  box-sizing: border-box;
  container-type: inline-size;
  width: 100%;
  padding: clamp(20px, 4cqw, 48px);
  background: var(--ac-bento-surface);
  color: var(--ac-bento-ink);
  font-family: var(--ac-bento-font);
}

.ac-feature-bento * { box-sizing: border-box; }
.ac-feature-bento-header { margin-bottom: 28px; }
.ac-feature-bento-header > span { font-size: 10px; font-weight: 600; letter-spacing: .12em; }
.ac-feature-bento-header h2 { margin: 12px 0 0; font-size: clamp(28px, 4cqw, 43px); font-weight: 500; line-height: 1.08; letter-spacing: -.05em; }
.ac-feature-bento-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-flow: row; gap: 16px; }
.ac-feature-bento-card { display: flex; flex-direction: column; min-width: 0; overflow: hidden; border: 1px solid var(--ac-bento-line); border-radius: 12px; background: var(--ac-bento-card); transition: transform .22s ease, border-color .22s; }
.ac-feature-bento-wide { grid-column: span 2; }
.ac-feature-bento-tall { grid-row: span 2; }
.ac-feature-bento-media { display: grid; place-items: center; min-width: 0; min-height: 180px; height: 200px; overflow: hidden; background: var(--ac-bento-media); pointer-events: none; }
.ac-feature-bento-tall .ac-feature-bento-media { flex: 1; min-height: 290px; }
.ac-feature-bento-media > img, .ac-feature-bento-media > video { display: block; width: 100%; height: 100%; object-fit: cover; }
.ac-feature-bento-copy { padding: 25px; }
.ac-feature-bento-eyebrow { display: block; margin-bottom: 9px; color: var(--ac-bento-muted); font-size: 9px; font-weight: 600; letter-spacing: .1em; }
.ac-feature-bento-card h3 { margin: 0; font-size: clamp(19px, 2.5cqw, 25px); line-height: 1.2; font-weight: 500; letter-spacing: -.04em; }
.ac-feature-bento-card p { max-width: 47ch; margin: 11px 0 0; color: var(--ac-bento-muted); font-size: 13px; line-height: 1.6; }
.ac-feature-bento-link { display: inline-flex; align-items: center; gap: 20px; margin-top: 17px; padding: 2px 0 6px; border-bottom: 1px solid var(--ac-bento-line); color: var(--ac-bento-ink); font-size: 12px; line-height: 1.5; text-decoration: none; }
.ac-feature-bento-link > span { font-size: 17px; transition: transform .2s; }
.ac-feature-bento-link:hover > span { transform: translate(2px, -2px); }
.ac-feature-bento-link:focus-visible { outline: 2px solid var(--ac-bento-accent); outline-offset: 5px; }
.ac-feature-bento-card:focus-within { border-color: var(--ac-bento-accent); }
@media (hover: hover) and (pointer: fine) {
  .ac-feature-bento-card:hover { transform: translateY(-3px); border-color: var(--ac-bento-accent); }
}
@container (max-width: 740px) {
  .ac-feature-bento-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ac-feature-bento-tall { grid-row: auto; }
  .ac-feature-bento-tall .ac-feature-bento-media { flex: initial; min-height: 180px; }
}
@container (max-width: 480px) {
  .ac-feature-bento-grid { grid-template-columns: minmax(0, 1fr); gap: 13px; }
  .ac-feature-bento-wide, .ac-feature-bento-tall { grid-column: auto; grid-row: auto; }
  .ac-feature-bento-copy { padding: 22px; }
}
@media (prefers-reduced-motion: reduce) {
  .ac-feature-bento-card, .ac-feature-bento-link > span { transition: none; }
  .ac-feature-bento-card:hover, .ac-feature-bento-link:hover > span { transform: none; }
}
